import { NextRequest, NextResponse } from 'next/server'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

const ALLOWED_MIME_TYPES = ['image/jpeg', 'image/png', 'image/webp', 'image/gif']
const MAX_BYTES = 10 * 1024 * 1024 // 10 MB

export async function POST(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  let formData: FormData
  try {
    formData = await request.formData()
  } catch {
    return NextResponse.json({ error: 'Invalid form data' }, { status: 400 })
  }

  const file = formData.get('file')
  if (!(file instanceof File)) {
    return NextResponse.json({ error: 'No file provided' }, { status: 400 })
  }

  if (!ALLOWED_MIME_TYPES.includes(file.type)) {
    return NextResponse.json(
      { error: `File type not allowed. Use: ${ALLOWED_MIME_TYPES.join(', ')}` },
      { status: 400 }
    )
  }

  if (file.size > MAX_BYTES) {
    return NextResponse.json(
      { error: `File must be under 10 MB. Yours is ${(file.size / 1024 / 1024).toFixed(1)} MB.` },
      { status: 400 }
    )
  }

  try {
    const supabase = await createClient()
    const ext = file.type.split('/')[1]
    const path = `${authUser.studioId}/cover.${ext}`

    const { error: uploadError } = await supabase.storage
      .from('studio-assets')
      .upload(path, file, {
        contentType: file.type,
        upsert: true,
      })

    if (uploadError) {
      logger.error({ err: uploadError, studioId: authUser.studioId }, 'cover image upload failed')
      return NextResponse.json({ error: 'Upload failed' }, { status: 500 })
    }

    const { data: urlData } = supabase.storage.from('studio-assets').getPublicUrl(path)

    return NextResponse.json({ url: urlData.publicUrl })
  } catch (err) {
    logger.error({ err, studioId: authUser.studioId }, 'cover image upload unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

'use client'

import { useState, useCallback, useRef } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { Skeleton } from '@/components/ui/skeleton'
import { toast } from 'sonner'
import { logger } from '@/lib/logger'
import { Upload, X, ExternalLink, Eye } from 'lucide-react'
import type { Database } from '@/lib/supabase/types'

type BookingPageSettings =
  Database['public']['Tables']['booking_page_settings']['Row']

interface FormState {
  intro_headline: string
  intro_body: string
  show_artist_profiles: boolean
  show_prices: boolean
  require_deposit_on_public: boolean
  lead_time_hours: number
  cancellation_policy: string
  aftercare_message: string
  cover_image_url: string
}

function settingsToForm(s: BookingPageSettings | null | undefined): FormState {
  return {
    intro_headline: s?.intro_headline ?? '',
    intro_body: s?.intro_body ?? '',
    show_artist_profiles: s?.show_artist_profiles ?? true,
    show_prices: s?.show_prices ?? true,
    require_deposit_on_public: s?.require_deposit_on_public ?? false,
    lead_time_hours: s?.lead_time_hours ?? 24,
    cancellation_policy: s?.cancellation_policy ?? '',
    aftercare_message: s?.aftercare_message ?? '',
    cover_image_url: s?.cover_image_url ?? '',
  }
}

export function BookingPageSettingsClient() {
  const queryClient = useQueryClient()
  const fileInputRef = useRef<HTMLInputElement>(null)
  const [uploadingCover, setUploadingCover] = useState(false)
  const [previewOpen, setPreviewOpen] = useState(false)

  const { data, isLoading } = useQuery<{ data: BookingPageSettings | null }>({
    queryKey: ['booking-page-settings'],
    queryFn: async () => {
      const res = await fetch('/api/booking-page-settings')
      if (!res.ok) throw new Error('Failed to fetch settings')
      return res.json() as Promise<{ data: BookingPageSettings | null }>
    },
  })

  const [form, setForm] = useState<FormState>(() => settingsToForm(null))
  const [isDirty, setIsDirty] = useState(false)

  // Sync form when data loads
  const [initialized, setInitialized] = useState(false)
  if (!initialized && data !== undefined) {
    setForm(settingsToForm(data.data))
    setInitialized(true)
  }

  const update = useCallback(
    <K extends keyof FormState>(key: K, value: FormState[K]) => {
      setForm((prev) => ({ ...prev, [key]: value }))
      setIsDirty(true)
    },
    []
  )

  const saveMutation = useMutation({
    mutationFn: async () => {
      const res = await fetch('/api/booking-page-settings', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          intro_headline: form.intro_headline || null,
          intro_body: form.intro_body || null,
          show_artist_profiles: form.show_artist_profiles,
          show_prices: form.show_prices,
          require_deposit_on_public: form.require_deposit_on_public,
          lead_time_hours: form.lead_time_hours,
          cancellation_policy: form.cancellation_policy || null,
          aftercare_message: form.aftercare_message || null,
          cover_image_url: form.cover_image_url || null,
        }),
      })
      if (!res.ok) {
        const err = await res.json() as { error?: string }
        throw new Error(err.error ?? 'Failed to save settings')
      }
    },
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ['booking-page-settings'] })
      setIsDirty(false)
      toast.success('Booking page settings saved')
    },
    onError: (err: Error) => {
      toast.error(err.message)
      logger.error({ err }, 'booking page settings save failed')
    },
  })

  const handleCoverUpload = useCallback(
    async (file: File) => {
      if (!['image/jpeg', 'image/png', 'image/webp', 'image/gif'].includes(file.type)) {
        toast.error('Use JPEG, PNG, WebP, or GIF images')
        return
      }
      if (file.size > 10 * 1024 * 1024) {
        toast.error('Image must be under 10 MB')
        return
      }

      setUploadingCover(true)
      try {
        const fd = new FormData()
        fd.append('file', file)
        const res = await fetch('/api/upload/cover-image', { method: 'POST', body: fd })
        if (!res.ok) {
          const err = await res.json() as { error?: string }
          throw new Error(err.error ?? 'Upload failed')
        }
        const { url } = await res.json() as { url: string }
        update('cover_image_url', url)
        toast.success('Cover image uploaded')
      } catch (err) {
        const message = err instanceof Error ? err.message : 'Upload failed'
        toast.error(message)
        logger.error({ err }, 'cover image upload failed')
      } finally {
        setUploadingCover(false)
      }
    },
    [update]
  )

  if (isLoading) {
    return (
      <div className="max-w-2xl space-y-6 p-6">
        <Skeleton className="h-8 w-64" />
        <Skeleton className="h-40 w-full" />
        <Skeleton className="h-24 w-full" />
        <Skeleton className="h-24 w-full" />
      </div>
    )
  }

  return (
    <div className="flex flex-col flex-1 overflow-hidden h-full">
      {/* Header */}
      <div className="flex items-center justify-between px-6 py-4 border-b border-border/40">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight">Booking page</h1>
          <p className="mt-0.5 text-sm text-muted-foreground">
            Configure your public booking page appearance
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            size="sm"
            className="h-8 text-xs gap-1.5"
            onClick={() => setPreviewOpen(true)}
          >
            <Eye className="h-3.5 w-3.5" />
            Preview
          </Button>
          <Button
            size="sm"
            className="h-8 text-xs"
            disabled={!isDirty || saveMutation.isPending}
            onClick={() => saveMutation.mutate()}
          >
            {saveMutation.isPending ? 'Saving...' : 'Save changes'}
          </Button>
        </div>
      </div>

      {/* Form */}
      <div className="flex-1 overflow-y-auto">
        <div className="max-w-2xl space-y-8 p-6">
          {/* Cover image */}
          <section className="space-y-3">
            <div>
              <h2 className="text-sm font-semibold">Cover image</h2>
              <p className="text-xs text-muted-foreground mt-0.5">
                Banner shown at the top of your public booking page. JPEG, PNG, WebP or GIF, max 10 MB.
              </p>
            </div>

            {form.cover_image_url ? (
              <div className="relative rounded-lg overflow-hidden border border-border/60 bg-muted/30">
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img
                  src={form.cover_image_url}
                  alt="Cover preview"
                  className="w-full h-32 object-cover"
                />
                <div className="absolute top-2 right-2 flex gap-1">
                  <Button
                    variant="outline"
                    size="icon"
                    className="h-7 w-7 bg-background/80 backdrop-blur-sm"
                    onClick={() => window.open(form.cover_image_url, '_blank')}
                  >
                    <ExternalLink className="h-3 w-3" />
                  </Button>
                  <Button
                    variant="outline"
                    size="icon"
                    className="h-7 w-7 bg-background/80 backdrop-blur-sm"
                    onClick={() => { update('cover_image_url', ''); }}
                  >
                    <X className="h-3 w-3" />
                  </Button>
                </div>
              </div>
            ) : (
              <div
                className="flex flex-col items-center justify-center rounded-lg border-2 border-dashed border-border/60 h-32 cursor-pointer hover:border-border transition-colors"
                onClick={() => fileInputRef.current?.click()}
                onDragOver={(e) => { e.preventDefault() }}
                onDrop={(e) => {
                  e.preventDefault()
                  const file = e.dataTransfer.files[0]
                  if (file) void handleCoverUpload(file)
                }}
              >
                <Upload className="h-6 w-6 text-muted-foreground/50 mb-2" />
                <p className="text-xs text-muted-foreground">
                  {uploadingCover ? 'Uploading...' : 'Click or drag to upload cover image'}
                </p>
              </div>
            )}

            <input
              ref={fileInputRef}
              type="file"
              accept="image/*"
              className="hidden"
              onChange={(e) => {
                const file = e.target.files?.[0]
                if (file) void handleCoverUpload(file)
                e.target.value = ''
              }}
            />
          </section>

          {/* Intro copy */}
          <section className="space-y-3">
            <div>
              <h2 className="text-sm font-semibold">Intro copy</h2>
              <p className="text-xs text-muted-foreground mt-0.5">
                Shown below the studio name on your booking page.
              </p>
            </div>

            <div className="space-y-1.5">
              <Label htmlFor="headline" className="text-xs">Headline</Label>
              <Input
                id="headline"
                value={form.intro_headline}
                onChange={(e) => update('intro_headline', e.target.value)}
                placeholder="Book your next session"
                maxLength={120}
                className="text-sm"
              />
            </div>

            <div className="space-y-1.5">
              <Label htmlFor="body" className="text-xs">Body text</Label>
              <Textarea
                id="body"
                value={form.intro_body}
                onChange={(e) => update('intro_body', e.target.value)}
                placeholder="Tell clients what to expect when booking with your studio..."
                className="text-sm min-h-[80px] resize-none"
                maxLength={1000}
              />
            </div>
          </section>

          {/* Display options */}
          <section className="space-y-3">
            <h2 className="text-sm font-semibold">Display options</h2>

            <div className="space-y-2">
              {[
                {
                  key: 'show_artist_profiles' as const,
                  label: 'Show artist profiles',
                  description: 'Let clients choose their preferred artist',
                },
                {
