import { NextRequest } from 'next/server'
import { z } from 'zod'
import { createPublicClient } from '@/lib/supabase/public'
import { publicBookingReadRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

interface Params {
  params: Promise<{ token: string }>
}

interface BookingData {
  booking_token: string
  scheduled_at: string
  end_at: string
  studio_name?: string
  service_name?: string
  artist_name?: string
  location_address?: string
}

function formatIcsDate(iso: string): string {
  return iso.replace(/[-:]/g, '').replace(/\.\d{3}/, '').replace('Z', 'Z')
}

function escapeIcs(str: string): string {
  return str.replace(/\\/g, '\\\\').replace(/;/g, '\\;').replace(/,/g, '\\,').replace(/\n/g, '\\n')
}

export async function GET(request: NextRequest, { params }: Params) {
  const ip = request.headers.get('x-forwarded-for') ?? 'anonymous'
  const { success } = await publicBookingReadRatelimit.limit(ip)
  if (!success) {
    return new Response('Too many requests', { status: 429 })
  }

  const { token } = await params
  if (!z.string().uuid().safeParse(token).success) {
    return new Response('Invalid token', { status: 400 })
  }

  try {
    const supabase = createPublicClient()
    const { data, error } = await supabase.rpc('public_get_booking_by_token', {
      p_token: token,
    })

    if (error || !data) {
      return new Response('Booking not found', { status: 404 })
    }

    const booking = data as BookingData

    const dtStart = formatIcsDate(booking.scheduled_at)
    const dtEnd = formatIcsDate(booking.end_at)
    const now = formatIcsDate(new Date().toISOString())
    const uid = `${booking.booking_token}@inkos`

    const summary = [booking.service_name, booking.studio_name].filter(Boolean).join(' @ ')
    const description = [
      booking.artist_name ? `Artist: ${booking.artist_name}` : null,
      `Booking ref: ${booking.booking_token}`,
    ]
      .filter(Boolean)
      .join('\\n')

    const location = booking.location_address ?? booking.studio_name ?? ''

    const ics = [
      'BEGIN:VCALENDAR',
      'VERSION:2.0',
      'PRODID:-//InkOS//Booking//EN',
      'CALSCALE:GREGORIAN',
      'METHOD:PUBLISH',
      'BEGIN:VEVENT',
      `UID:${uid}`,
      `DTSTAMP:${now}`,
      `DTSTART:${dtStart}`,
      `DTEND:${dtEnd}`,
      `SUMMARY:${escapeIcs(summary || 'Tattoo appointment')}`,
      `DESCRIPTION:${description}`,
      location ? `LOCATION:${escapeIcs(location)}` : null,
      'STATUS:CONFIRMED',
      'END:VEVENT',
      'END:VCALENDAR',
    ]
      .filter(Boolean)
      .join('\r\n')

    return new Response(ics, {
      status: 200,
      headers: {
        'Content-Type': 'text/calendar; charset=utf-8',
        'Content-Disposition': `attachment; filename="booking-${booking.booking_token.split('-')[0]}.ics"`,
        'Cache-Control': 'no-store',
      },
    })
  } catch (err) {
    logger.error({ err, token }, 'ics download unexpected error')
    return new Response('Internal server error', { status: 500 })
  }
}

