'use client'

import { use, useState } from 'react'
import { useQuery } from '@tanstack/react-query'
import { Skeleton } from '@/components/ui/skeleton'
import { Button } from '@/components/ui/button'
import { useRouter } from 'next/navigation'
import { formatCurrency } from '@/lib/utils'
import { Clock, ChevronRight } from 'lucide-react'

interface StudioPublic {
  id: string
  name: string
  slug: string
  brand_color: string | null
  logo_url: string | null
  cover_image_url?: string | null
  intro_headline?: string | null
  intro_body?: string | null
  show_prices?: boolean
  show_artist_profiles?: boolean
}

interface ServicePublic {
  id: string
  name: string
  description: string | null
  duration_min: number
  base_price_cents: number
  deposit_cents: number
  deposit_required: boolean
  color: string | null
}

interface ArtistPublic {
  id: string
  display_name: string
  avatar_url: string | null
  bio: string | null
  specialties: string[]
}

export default function BookStudioPage({
  params,
}: {
  params: Promise<{ studioSlug: string }>
}) {
  const { studioSlug } = use(params)
  const router = useRouter()

  const { data: studioData, isLoading: studioLoading, error: studioError } = useQuery<{ data: StudioPublic }>({
    queryKey: ['public', 'studio', studioSlug],
    queryFn: async () => {
      const res = await fetch(`/api/public/studios/${studioSlug}`)
      if (!res.ok) throw new Error('Studio not found')
      return res.json() as Promise<{ data: StudioPublic }>
    },
  })

  const studio = studioData?.data
  const studioId = studio?.id

  const { data: servicesData, isLoading: servicesLoading } = useQuery<{ data: ServicePublic[] }>({
    queryKey: ['public', 'services', studioId],
    queryFn: async () => {
      const res = await fetch(`/api/public/studios/${studioSlug}/services`)
      if (!res.ok) throw new Error('Failed to load services')
      return res.json() as Promise<{ data: ServicePublic[] }>
    },
    enabled: !!studioId,
  })

  const { data: artistsData } = useQuery<{ data: ArtistPublic[] }>({
    queryKey: ['public', 'artists', studioId],
    queryFn: async () => {
      const res = await fetch(`/api/public/studios/${studioSlug}/artists`)
      if (!res.ok) throw new Error('Failed to load artists')
      return res.json() as Promise<{ data: ArtistPublic[] }>
    },
    enabled: !!studioId && studio?.show_artist_profiles !== false,
  })

  const brandColor = studio?.brand_color ?? null
  const services = servicesData?.data ?? []
  const artists = artistsData?.data ?? []

  if (studioError) {
    return (
      <div className="min-h-svh flex items-center justify-center p-6">
        <div className="text-center space-y-3">
          <p className="text-lg font-semibold">Studio not found</p>
          <p className="text-sm text-muted-foreground">
            The booking page you&apos;re looking for doesn&apos;t exist.
          </p>
        </div>
      </div>
    )
  }

  return (
    <div
      className="min-h-svh"
      style={brandColor ? ({ '--booking-brand': brandColor } as React.CSSProperties) : undefined}
    >
      {/* Hero / header */}
      {studioLoading ? (
        <div className="h-40 bg-muted animate-pulse" />
      ) : (
        <div
          className="relative"
          style={
            brandColor
              ? { background: `linear-gradient(135deg, ${brandColor}20, ${brandColor}08)` }
              : undefined
          }
        >
          <div className="max-w-2xl mx-auto px-4 py-10">
            {studio?.logo_url && (
              // eslint-disable-next-line @next/next/no-img-element
              <img
                src={studio.logo_url}
                alt={studio.name}
                className="h-10 object-contain mb-4"
              />
            )}
            <h1 className="text-3xl font-bold tracking-tight">
              {studio?.intro_headline ?? `Book with ${studio?.name ?? ''}`}
            </h1>
            {studio?.intro_body && (
              <p className="mt-2 text-sm text-muted-foreground max-w-md">
                {studio.intro_body}
              </p>
            )}
          </div>
        </div>
      )}

      <div className="max-w-2xl mx-auto px-4 py-8 space-y-8">
        {/* Services */}
        <section className="space-y-3">
          <h2 className="text-base font-semibold">Choose a service</h2>

          {servicesLoading || studioLoading ? (
            <div className="space-y-2">
              {Array.from({ length: 4 }).map((_, i) => (
                <Skeleton key={i} className="h-16 w-full rounded-xl" />
              ))}
            </div>
          ) : services.length === 0 ? (
            <p className="text-sm text-muted-foreground">
              No services available for booking.
            </p>
          ) : (
            <div className="space-y-2">
              {services.map((service) => (
                <button
                  key={service.id}
                  className="booking-service-card w-full flex items-center justify-between"
                  onClick={() => router.push(`/book/${studioSlug}/${service.id}`)}
                >
                  <div className="flex items-center gap-3 min-w-0">
                    {service.color && (
                      <span
                        className="h-3 w-3 rounded-full shrink-0"
                        style={{ backgroundColor: service.color }}
                      />
                    )}
                    <div className="min-w-0 text-left">
                      <p className="text-sm font-medium">{service.name}</p>
                      {service.description && (
                        <p className="text-xs text-muted-foreground truncate max-w-[280px]">
                          {service.description}
                        </p>
                      )}
                      <p className="text-xs text-muted-foreground flex items-center gap-1 mt-0.5">
                        <Clock className="h-3 w-3" />
                        {service.duration_min} min
                        {studio?.show_prices !== false && (
                          <> · {formatCurrency(service.base_price_cents)}</>
                        )}
                      </p>
                    </div>
                  </div>
                  <ChevronRight className="h-4 w-4 text-muted-foreground shrink-0" />
                </button>
              ))}
            </div>
          )}
        </section>

        {/* Artist profiles */}
        {studio?.show_artist_profiles !== false && artists.length > 0 && (
          <section className="space-y-3">
            <h2 className="text-base font-semibold">Our artists</h2>
            <div className="grid grid-cols-2 gap-3 sm:grid-cols-3">
              {artists.map((artist) => (
                <div
                  key={artist.id}
                  className="rounded-xl border border-border/60 p-3 text-center space-y-2"
                >
                  <div className="h-12 w-12 rounded-full bg-muted mx-auto flex items-center justify-center overflow-hidden">
                    {artist.avatar_url ? (
                      // eslint-disable-next-line @next/next/no-img-element
                      <img
                        src={artist.avatar_url}
                        alt={artist.display_name}
                        className="h-full w-full object-cover"
                      />
                    ) : (
                      <span className="text-lg font-medium">
                        {artist.display_name[0]}
                      </span>
                    )}
                  </div>
                  <p className="text-sm font-medium">{artist.display_name}</p>
                  {artist.specialties.length > 0 && (
                    <p className="text-xs text-muted-foreground truncate">
                      {artist.specialties.slice(0, 2).join(', ')}
                    </p>
                  )}
                </div>
              ))}
            </div>
          </section>
        )}
      </div>
    </div>
  )
}

