    // First resolve studio id from slug
    const { data: studio, error: studioError } = await supabase
      .rpc('public_get_studio_by_slug', { p_slug: slug })

    if (studioError || !studio) {
      return NextResponse.json({ error: 'Studio not found' }, { status: 404 })
    }

    const studioObj = studio as { id: string }
    const { data, error } = await supabase
      .rpc('public_get_services_for_studio', { p_studio_id: studioObj.id })

    if (error) {
      logger.error({ err: error, slug }, 'public services fetch failed')
      return NextResponse.json({ error: 'Failed to fetch services' }, { status: 500 })
    }

    return NextResponse.json({ data: data ?? [] })
  } catch (err) {
    logger.error({ err, slug }, 'public services GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { createPublicClient } from '@/lib/supabase/public'
import { publicBookingReadRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

interface Params {
  params: Promise<{ slug: string }>
}

export async function GET(request: NextRequest, { params }: Params) {
  const ip = request.headers.get('x-forwarded-for') ?? 'anonymous'
  const { success } = await publicBookingReadRatelimit.limit(ip)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { slug } = await params
  if (!z.string().min(1).max(100).safeParse(slug).success) {
    return NextResponse.json({ error: 'Invalid slug' }, { status: 400 })
  }

  try {
    const supabase = createPublicClient()

    const { data: studio, error: studioError } = await supabase
      .rpc('public_get_studio_by_slug', { p_slug: slug })

    if (studioError || !studio) {
      return NextResponse.json({ error: 'Studio not found' }, { status: 404 })
    }

    const studioObj = studio as { id: string }
    const { data, error } = await supabase
      .rpc('public_get_artists_for_studio', { p_studio_id: studioObj.id })

    if (error) {
      logger.error({ err: error, slug }, 'public artists fetch failed')
      return NextResponse.json({ error: 'Failed to fetch artists' }, { status: 500 })
    }

    return NextResponse.json({ data: data ?? [] })
  } catch (err) {
    logger.error({ err, slug }, 'public artists GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

'use client'

import { use, useState, useCallback } from 'react'
import { useQuery, useMutation } from '@tanstack/react-query'
import { Skeleton } from '@/components/ui/skeleton'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { SlotPicker } from '@/components/booking/SlotPicker'
import { toast } from 'sonner'
import { useRouter } from 'next/navigation'
import { formatCurrency } from '@/lib/utils'
import { ChevronLeft, ChevronRight, Clock, Check, User } from 'lucide-react'
import { cn } from '@/lib/utils'
import { z } from 'zod'

const ClientFormSchema = z.object({
  first_name: z.string().min(1, 'First name is required').max(100),
  last_name: z.string().max(100).optional(),
  email: z.string().email('Enter a valid email'),
  phone: z.string().max(30).optional(),
})

type ClientFormData = z.infer<typeof ClientFormSchema>

interface ArtistPublic {
  id: string
  display_name: string
  avatar_url: string | null
  bio: string | null
  specialties: string[]
}

interface ServicePublic {
  id: string
  name: string
  description: string | null
  duration_min: number
  base_price_cents: number
  deposit_cents: number
  deposit_required: boolean
  color: string | null
}

interface StudioPublic {
  id: string
  name: string
  slug: string
  brand_color: string | null
}

const STEPS = ['Artist', 'Time', 'Details']

export default function BookServicePage({
  params,
}: {
  params: Promise<{ studioSlug: string; serviceId: string }>
}) {
  const { studioSlug, serviceId } = use(params)
  const router = useRouter()

  const [step, setStep] = useState(0)
  const [selectedArtistId, setSelectedArtistId] = useState<string | null>(null)
  const [selectedSlot, setSelectedSlot] = useState<string | null>(null)
  const [clientForm, setClientForm] = useState<ClientFormData>({
    first_name: '',
    last_name: '',
    email: '',
    phone: '',
  })
  const [formErrors, setFormErrors] = useState<Partial<Record<keyof ClientFormData, string>>>({})

  const { data: studioData } = useQuery<{ data: StudioPublic }>({
    queryKey: ['public', 'studio', studioSlug],
    queryFn: async () => {
      const res = await fetch(`/api/public/studios/${studioSlug}`)
      if (!res.ok) throw new Error('Studio not found')
      return res.json() as Promise<{ data: StudioPublic }>
    },
  })

  const { data: serviceData, isLoading: serviceLoading } = useQuery<{ data: ServicePublic[] }>({
    queryKey: ['public', 'services', studioData?.data.id],
    queryFn: async () => {
      const res = await fetch(`/api/public/studios/${studioSlug}/services`)
      if (!res.ok) throw new Error('Failed to load service')
      return res.json() as Promise<{ data: ServicePublic[] }>
    },
    enabled: !!studioData,
  })

  const { data: artistsData, isLoading: artistsLoading } = useQuery<{ data: ArtistPublic[] }>({
    queryKey: ['public', 'artists', studioData?.data.id],
    queryFn: async () => {
      const res = await fetch(`/api/public/studios/${studioSlug}/artists`)
      if (!res.ok) throw new Error('Failed to load artists')
      return res.json() as Promise<{ data: ArtistPublic[] }>
    },
    enabled: !!studioData,
  })

  const studio = studioData?.data
  const service = serviceData?.data.find((s) => s.id === serviceId)
  const artists = artistsData?.data ?? []
  const brandColor = studio?.brand_color ?? null

  const bookMutation = useMutation({
    mutationFn: async () => {
      if (!selectedArtistId || !selectedSlot || !service) {
        throw new Error('Missing required booking data')
      }

      const token = crypto.randomUUID()
      const res = await fetch('/api/public/bookings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          token,
          studio_slug: studioSlug,
          service_id: serviceId,
          artist_id: selectedArtistId,
          scheduled_at: selectedSlot,
          client_data: {
            first_name: clientForm.first_name,
            last_name: clientForm.last_name || undefined,
            email: clientForm.email,
            phone: clientForm.phone || undefined,
          },
        }),
      })

      if (!res.ok) {
        const err = await res.json() as { error?: string }
        if (res.status === 409) {
          throw new Error('That time slot is no longer available. Please pick another time.')
        }
        throw new Error(err.error ?? 'Failed to create booking')
      }

      const { data } = await res.json() as { data: { booking_token: string } }
      return data.booking_token
    },
    onSuccess: (bookingToken) => {
      router.push(`/book/${studioSlug}/confirmation/${bookingToken}`)
    },
    onError: (err: Error) => {
      if (err.message.includes('time slot')) {
        toast.error(err.message)
        setStep(1) // back to time picker
        setSelectedSlot(null)
      } else {
        toast.error(err.message)
      }
    },
  })

  const validateClientForm = useCallback((): boolean => {
    const result = ClientFormSchema.safeParse(clientForm)
    if (!result.success) {
      const errors: Partial<Record<keyof ClientFormData, string>> = {}
      result.error.issues.forEach((issue) => {
        const key = issue.path[0] as keyof ClientFormData
        if (!errors[key]) errors[key] = issue.message
      })
      setFormErrors(errors)
      return false
    }
    setFormErrors({})
    return true
  }, [clientForm])

  const handleNextOrBook = useCallback(() => {
    if (step < STEPS.length - 1) {
      setStep((s) => s + 1)
    } else {
      if (!validateClientForm()) return
      bookMutation.mutate()
    }
  }, [step, validateClientForm, bookMutation])

  const canProceed =
    (step === 0 && !!selectedArtistId) ||
    (step === 1 && !!selectedSlot) ||
    step === 2

  if (serviceLoading || !service) {
    return (
      <div className="max-w-lg mx-auto px-4 py-10 space-y-4">
        <Skeleton className="h-8 w-48" />
        <Skeleton className="h-24 w-full" />
        <Skeleton className="h-64 w-full" />
      </div>
    )
  }

  return (
    <div
      className="min-h-svh"
      style={brandColor ? ({ '--booking-brand': brandColor } as React.CSSProperties) : undefined}
    >
      {/* Header */}
      <div
        className="border-b border-border/40"
        style={
          brandColor
            ? { background: `linear-gradient(135deg, ${brandColor}15, ${brandColor}05)` }
            : undefined
        }
      >
        <div className="max-w-lg mx-auto px-4 py-4 flex items-center gap-3">
          <Button
            variant="ghost"
            size="icon"
            className="h-8 w-8 shrink-0"
            onClick={() => (step > 0 ? setStep((s) => s - 1) : router.push(`/book/${studioSlug}`))}
          >
            <ChevronLeft className="h-4 w-4" />
          </Button>

          <div className="min-w-0">
            <p className="text-xs text-muted-foreground">{studio?.name}</p>
            <div className="flex items-center gap-1.5">
              {service.color && (
                <span
                  className="h-2 w-2 rounded-full shrink-0"
                  style={{ backgroundColor: service.color }}
                />
              )}
              <h1 className="text-base font-semibold truncate">{service.name}</h1>
            </div>
            <p className="text-xs text-muted-foreground flex items-center gap-1">
              <Clock className="h-3 w-3" />
              {service.duration_min} min · {formatCurrency(service.base_price_cents)}
            </p>
          </div>
        </div>

        {/* Step indicator */}
        <div className="max-w-lg mx-auto px-4 pb-4">
          <div className="flex items-center gap-2">
            {STEPS.map((label, index) => (
              <div key={label} className="flex items-center gap-2">
                <div className="flex items-center gap-1.5">
                  <div
                    className={cn(
                      'h-5 w-5 rounded-full flex items-center justify-center text-xs font-medium transition-all',
                      index < step
                        ? 'bg-primary text-primary-foreground'
                        : index === step
                          ? 'border-2 border-primary text-primary'
                          : 'border-2 border-border text-muted-foreground'
                    )}
                  >
                    {index < step ? <Check className="h-3 w-3" /> : index + 1}
                  </div>
                  <span
                    className={cn(
                      'text-xs font-medium',
                      index === step ? 'text-foreground' : 'text-muted-foreground'
                    )}
                  >
                    {label}
                  </span>
                </div>
                {index < STEPS.length - 1 && (
                  <div
                    className={cn(
                      'h-px flex-1 min-w-[16px]',
                      index < step ? 'bg-primary' : 'bg-border'
                    )}
                  />
                )}
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Step content */}
      <div className="max-w-lg mx-auto px-4 py-6 space-y-4">
        {/* Step 0: Artist */}
        {step === 0 && (
          <div className="space-y-3">
            <h2 className="text-base font-semibold">Choose an artist</h2>
            {artistsLoading ? (
              <div className="space-y-2">
                {Array.from({ length: 3 }).map((_, i) => (
                  <Skeleton key={i} className="h-16 w-full rounded-xl" />
                ))}
              </div>
            ) : artists.length === 0 ? (
              <p className="text-sm text-muted-foreground">No artists available.</p>
            ) : (
              <div className="space-y-2">
                {artists.map((artist) => (
                  <button
                    key={artist.id}
                    className={cn(
                      'w-full flex items-center gap-3 rounded-xl border p-3 text-left transition-all hover:bg-muted/50',
                      selectedArtistId === artist.id
                        ? 'border-primary bg-primary/5'
                        : 'border-border/60'
                    )}
                    onClick={() => setSelectedArtistId(artist.id)}
                  >
                    <div className="h-10 w-10 rounded-full bg-muted flex items-center justify-center shrink-0 overflow-hidden">
                      {artist.avatar_url ? (
                        // eslint-disable-next-line @next/next/no-img-element
                        <img
                          src={artist.avatar_url}
                          alt={artist.display_name}
                          className="h-full w-full object-cover"
                        />
                      ) : (
                        <User className="h-4 w-4 text-muted-foreground" />
                      )}
                    </div>
                    <div className="min-w-0">
                      <p className="text-sm font-medium">{artist.display_name}</p>
                      {artist.specialties.length > 0 && (
                        <p className="text-xs text-muted-foreground truncate">
                          {artist.specialties.slice(0, 2).join(', ')}
                        </p>
                      )}
                    </div>
                    {selectedArtistId === artist.id && (
                      <Check className="h-4 w-4 text-primary ml-auto shrink-0" />
                    )}
                  </button>
                ))}
              </div>
            )}
          </div>
        )}

        {/* Step 1: Time */}
        {step === 1 && (
          <div className="space-y-3">
            <h2 className="text-base font-semibold">Pick a time</h2>
            <SlotPicker
              artistId={selectedArtistId}
              serviceId={serviceId}
              selectedSlot={selectedSlot}
              onSelectSlot={setSelectedSlot}
            />
          </div>
        )}

        {/* Step 2: Client details (inline form — approved deviation #2) */}
        {step === 2 && (
          <div className="space-y-4">
            <h2 className="text-base font-semibold">Your details</h2>

            {/* Booking summary */}
            {selectedSlot && (
              <div className="rounded-lg bg-muted/40 border border-border/60 p-3 space-y-1 text-sm">
                <p className="font-medium text-xs text-muted-foreground uppercase tracking-wide">Summary</p>
                <p>{service.name}</p>
                <p className="text-xs text-muted-foreground tabular-nums">
                  {new Date(selectedSlot).toLocaleDateString('en-US', {
                    weekday: 'short',
                    month: 'short',
                    day: 'numeric',
                    hour: '2-digit',
                    minute: '2-digit',
                  })}
                </p>
                <p className="font-medium tabular-nums">{formatCurrency(service.base_price_cents)}</p>
                {service.deposit_required && service.deposit_cents > 0 && (
                  <p className="text-xs text-amber-600 dark:text-amber-400">
                    Deposit required: {formatCurrency(service.deposit_cents)}
                  </p>
                )}
              </div>
            )}

            {/* Client form */}
            <div className="space-y-3">
              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1.5">
                  <Label htmlFor="first_name" className="text-xs">First name *</Label>
                  <Input
                    id="first_name"
                    value={clientForm.first_name}
                    onChange={(e) => {
                      setClientForm((p) => ({ ...p, first_name: e.target.value }))
                      if (formErrors.first_name) setFormErrors((p) => ({ ...p, first_name: undefined }))
                    }}
                    placeholder="Jane"
                    className={cn('text-sm', formErrors.first_name && 'border-destructive')}
                  />
                  {formErrors.first_name && (
                    <p className="text-xs text-destructive">{formErrors.first_name}</p>
                  )}
                </div>

                <div className="space-y-1.5">
                  <Label htmlFor="last_name" className="text-xs">Last name</Label>
                  <Input
                    id="last_name"
                    value={clientForm.last_name}
                    onChange={(e) => setClientForm((p) => ({ ...p, last_name: e.target.value }))}
                    placeholder="Doe"
                    className="text-sm"
                  />
                </div>
              </div>

              <div className="space-y-1.5">
                <Label htmlFor="pub_email" className="text-xs">Email *</Label>
                <Input
                  id="pub_email"
                  type="email"
                  value={clientForm.email}
                  onChange={(e) => {
                    setClientForm((p) => ({ ...p, email: e.target.value }))
                    if (formErrors.email) setFormErrors((p) => ({ ...p, email: undefined }))
                  }}
                  placeholder="jane@example.com"
                  className={cn('text-sm', formErrors.email && 'border-destructive')}
                />
                {formErrors.email && (
                  <p className="text-xs text-destructive">{formErrors.email}</p>
                )}
              </div>

              <div className="space-y-1.5">
                <Label htmlFor="pub_phone" className="text-xs">Phone</Label>
                <Input
                  id="pub_phone"
                  type="tel"
                  value={clientForm.phone}
                  onChange={(e) => setClientForm((p) => ({ ...p, phone: e.target.value }))}
                  placeholder="+1 (555) 000-0000"
                  className="text-sm"
                />
              </div>
            </div>

            {/* Deposit stub */}
            {service.deposit_required && service.deposit_cents > 0 && (
              <div className="rounded-lg border border-amber-200 dark:border-amber-800 bg-amber-50 dark:bg-amber-950/30 p-3 space-y-2">
                <p className="text-sm font-medium text-amber-800 dark:text-amber-300">
                  Deposit required: {formatCurrency(service.deposit_cents)}
                </p>
                <Button
                  variant="outline"
                  size="sm"
                  className="w-full h-8 text-xs"
                  disabled
                  data-testid="deposit-cta"
                >
                  Pay deposit — available Sprint 4
                </Button>
              </div>
            )}
          </div>
        )}

        {/* Navigation */}
        <div className="flex items-center justify-between pt-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() =>
              step > 0 ? setStep((s) => s - 1) : router.push(`/book/${studioSlug}`)
            }
          >
            <ChevronLeft className="h-4 w-4 mr-1" />
            {step === 0 ? 'Back' : 'Previous'}
          </Button>

          <Button
            size="sm"
            disabled={!canProceed || bookMutation.isPending}
            onClick={handleNextOrBook}
          >
            {bookMutation.isPending
              ? 'Booking...'
              : step === STEPS.length - 1
                ? 'Confirm booking'
                : 'Next'}
            {step < STEPS.length - 1 && !bookMutation.isPending && (
              <ChevronRight className="h-4 w-4 ml-1" />
            )}
          </Button>
        </div>
      </div>
    </div>
  )
}

import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

const ALLOWED_MIME_TYPES = ['image/jpeg', 'image/png', 'image/webp', 'image/gif', 'image/heic']
const MAX_BYTES = 10 * 1024 * 1024 // 10 MB

type PhotoKind = 'reference' | 'before' | 'during' | 'after' | 'healed'
const PHOTO_KINDS: PhotoKind[] = ['reference', 'before', 'during', 'after', 'healed']

export async function POST(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  let formData: FormData
  try {
    formData = await request.formData()
  } catch {
    return NextResponse.json({ error: 'Invalid form data' }, { status: 400 })
  }

  const file = formData.get('file')
  const bookingId = formData.get('booking_id')
  const clientId = formData.get('client_id')
  const kind = formData.get('kind')
  const caption = formData.get('caption')

  if (!(file instanceof File)) {
    return NextResponse.json({ error: 'No file provided' }, { status: 400 })
  }

  const metaValidation = z.object({
    booking_id: z.string().uuid(),
    client_id: z.string().uuid(),
    kind: z.enum(['reference', 'before', 'during', 'after', 'healed']),
    caption: z.string().max(500).optional(),
  }).safeParse({
    booking_id: bookingId,
    client_id: clientId,
    kind,
    caption: caption ?? undefined,
  })

  if (!metaValidation.success) {
    return NextResponse.json({ error: metaValidation.error.flatten() }, { status: 400 })
  }

  // MIME type validation
  const mime = file.type as string
  if (!ALLOWED_MIME_TYPES.some((t) => mime.startsWith('image/'))) {
    return NextResponse.json(
      { error: 'Only image files are allowed (JPEG, PNG, WebP, GIF, HEIC)' },
      { status: 400 }
    )
  }
  if (!ALLOWED_MIME_TYPES.includes(mime)) {
    return NextResponse.json(
      { error: `File type ${mime} not allowed` },
      { status: 400 }
    )
  }

  if (file.size > MAX_BYTES) {
    return NextResponse.json(
      { error: `File must be under 10 MB. Yours is ${(file.size / 1024 / 1024).toFixed(1)} MB.` },
      { status: 400 }
    )
  }

  const { booking_id, client_id, kind: photoKind, caption: photoCaption } = metaValidation.data

  try {
    const supabase = await createClient()

    // Verify booking belongs to this studio
    const { data: booking, error: bookingError } = await supabase
      .from('bookings')
      .select('id, client_id')
      .eq('id', booking_id)
      .eq('studio_id', authUser.studioId)
      .single()

    if (bookingError || !booking) {
      return NextResponse.json({ error: 'Booking not found' }, { status: 404 })
    }

    // Generate storage path: {studio_id}/bookings/{booking_id}/{kind}-{timestamp}.{ext}
    const ext = mime.split('/')[1]
    const timestamp = Date.now()
    const path = `${authUser.studioId}/bookings/${booking_id}/${photoKind}-${timestamp}.${ext}`

    const { error: uploadError } = await supabase.storage
      .from('design-assets')
      .upload(path, file, {
        contentType: mime,
        upsert: false,
      })

    if (uploadError) {
      logger.error({ err: uploadError, bookingId: booking_id }, 'booking photo upload failed')
      return NextResponse.json({ error: 'Upload failed' }, { status: 500 })
    }

    // Get signed URL (1 hour expiry)
    const { data: signedUrl } = await supabase.storage
      .from('design-assets')
      .createSignedUrl(path, 3600)

    // Insert photo record
    const { data: photo, error: insertError } = await supabase
      .from('booking_photos')
      .insert({
        studio_id: authUser.studioId,
        booking_id,
        client_id,
        storage_path: path,
        kind: photoKind as PhotoKind,
        caption: photoCaption ?? null,
        uploaded_by: authUser.user.id,
      })
      .select('id, kind, caption, taken_at, storage_path')
      .single()

    if (insertError) {
      // Try to clean up orphaned storage file
      await supabase.storage.from('design-assets').remove([path]).catch(() => undefined)
      logger.error({ err: insertError, bookingId: booking_id }, 'booking photo insert failed')
      return NextResponse.json({ error: 'Failed to save photo record' }, { status: 500 })
    }

    return NextResponse.json({
      data: {
        ...photo,
        signed_url: signedUrl?.signedUrl ?? null,
      },
    }, { status: 201 })
  } catch (err) {
    logger.error({ err, bookingId: booking_id }, 'booking photo upload unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

'use client'

import { useState, useRef, useCallback } from 'react'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { Button } from '@/components/ui/button'
import { Skeleton } from '@/components/ui/skeleton'
import { toast } from 'sonner'
import { logger } from '@/lib/logger'
import {
  ImagePlus,
  X,
  ChevronLeft,
  ChevronRight,
  Upload,
} from 'lucide-react'
import { cn } from '@/lib/utils'
import type { Database } from '@/lib/supabase/types'

type PhotoKind = Database['public']['Tables']['booking_photos']['Row']['kind']

const PHOTO_KIND_LABELS: Record<PhotoKind, string> = {
  reference: 'Reference',
  before: 'Before',
  during: 'During',
  after: 'After',
  healed: 'Healed',
}

const PHOTO_KIND_ORDER: PhotoKind[] = ['reference', 'before', 'during', 'after', 'healed']

interface SignedPhoto {
  id: string
  kind: PhotoKind
  caption: string | null
  taken_at: string
  storage_path: string
  signed_url?: string | null
}

interface PhotoGalleryProps {
  bookingId: string
  clientId: string
  initialPhotos?: Database['public']['Tables']['booking_photos']['Row'][]
}

export function PhotoGallery({ bookingId, clientId, initialPhotos = [] }: PhotoGalleryProps) {
  const queryClient = useQueryClient()
  const fileInputRef = useRef<HTMLInputElement>(null)
  const [lightboxIndex, setLightboxIndex] = useState<number | null>(null)
  const [selectedKind, setSelectedKind] = useState<PhotoKind>('after')
  const [uploading, setUploading] = useState(false)

  // Fetch signed URLs for photos
  const { data: photosWithUrls, isLoading } = useQuery<SignedPhoto[]>({
    queryKey: ['booking-photos', bookingId],
    queryFn: async () => {
      const res = await fetch(`/api/bookings/${bookingId}/photos`)
      if (!res.ok) throw new Error('Failed to load photos')
      const json = await res.json() as { data: SignedPhoto[] }
      return json.data
    },
    initialData: initialPhotos as SignedPhoto[],
    staleTime: 55 * 60_000, // just under 1hr signed URL expiry
  })

  const deleteMutation = useMutation({
    mutationFn: async (photoId: string) => {
      const res = await fetch(`/api/bookings/${bookingId}/photos/${photoId}`, {
        method: 'DELETE',
      })
      if (!res.ok) {
        const err = await res.json() as { error?: string }
        throw new Error(err.error ?? 'Failed to delete photo')
      }
    },
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ['booking-photos', bookingId] })
      void queryClient.invalidateQueries({ queryKey: ['booking', bookingId] })
      if (lightboxIndex !== null) setLightboxIndex(null)
      toast.success('Photo removed')
    },
    onError: (err: Error) => {
      toast.error(err.message)
      logger.error({ err, bookingId }, 'photo delete failed')
    },
  })

  const handleUpload = useCallback(
    async (file: File) => {
      if (!file.type.startsWith('image/')) {
        toast.error('Only image files are allowed')
        return
      }
      if (file.size > 10 * 1024 * 1024) {
        toast.error('Image must be under 10 MB')
        return
      }

      setUploading(true)
      try {
        const fd = new FormData()
        fd.append('file', file)
        fd.append('booking_id', bookingId)
        fd.append('client_id', clientId)
        fd.append('kind', selectedKind)

        const res = await fetch('/api/upload/booking-photo', { method: 'POST', body: fd })
        if (!res.ok) {
          const err = await res.json() as { error?: string }
          throw new Error(err.error ?? 'Upload failed')
        }
        void queryClient.invalidateQueries({ queryKey: ['booking-photos', bookingId] })
        void queryClient.invalidateQueries({ queryKey: ['booking', bookingId] })
        toast.success('Photo uploaded')
      } catch (err) {
        const message = err instanceof Error ? err.message : 'Upload failed'
        toast.error(message)
        logger.error({ err, bookingId }, 'photo upload failed')
      } finally {
        setUploading(false)
      }
    },
    [bookingId, clientId, selectedKind, queryClient]
  )

  const photos = photosWithUrls ?? []

  // Group by kind for display
  const grouped = PHOTO_KIND_ORDER.reduce<Record<PhotoKind, SignedPhoto[]>>(
    (acc, k) => {
      acc[k] = photos.filter((p) => p.kind === k)
      return acc
    },
    {} as Record<PhotoKind, SignedPhoto[]>
  )

  return (
    <div className="space-y-4">
      {/* Upload controls */}
      <div className="flex flex-wrap items-center gap-2">
        <select
          value={selectedKind}
          onChange={(e) => setSelectedKind(e.target.value as PhotoKind)}
          className="h-8 rounded-md border border-input bg-background px-2 text-xs text-foreground"
        >
          {PHOTO_KIND_ORDER.map((k) => (
            <option key={k} value={k}>{PHOTO_KIND_LABELS[k]}</option>
          ))}
        </select>

        <Button
          variant="outline"
          size="sm"
          className="h-8 text-xs gap-1.5"
          disabled={uploading}
          onClick={() => fileInputRef.current?.click()}
        >
          {uploading ? (
            <>
              <Upload className="h-3.5 w-3.5 animate-pulse" />
              Uploading...
            </>
          ) : (
            <>
              <ImagePlus className="h-3.5 w-3.5" />
              Add photo
            </>
          )}
        </Button>

        <input
          ref={fileInputRef}
          type="file"
          accept="image/*"
          className="hidden"
          multiple
          onChange={(e) => {
            const files = Array.from(e.target.files ?? [])
            void Promise.all(files.map((f) => handleUpload(f)))
            e.target.value = ''
          }}
        />
      </div>

      {isLoading ? (
        <div className="grid grid-cols-3 gap-2">
          {Array.from({ length: 3 }).map((_, i) => (
            <Skeleton key={i} className="aspect-square rounded-md" />
          ))}
        </div>
      ) : photos.length === 0 ? (
        <div
          className="flex flex-col items-center justify-center py-8 gap-3 rounded-lg border-2 border-dashed border-border/60 cursor-pointer hover:border-border transition-colors"
          onClick={() => fileInputRef.current?.click()}
          onDragOver={(e) => e.preventDefault()}
          onDrop={(e) => {
            e.preventDefault()
            const files = Array.from(e.dataTransfer.files)
            void Promise.all(files.map((f) => handleUpload(f)))
          }}
        >
          <div className="rounded-xl bg-muted/50 p-3">
            <ImagePlus className="h-6 w-6 text-muted-foreground/50" />
          </div>
          <div className="text-center space-y-1">
            <p className="text-sm font-medium">No photos yet</p>
            <p className="text-xs text-muted-foreground">
              Click or drag &amp; drop to add reference, before &amp; after photos
            </p>
          </div>
        </div>
      ) : (
        <div className="space-y-4">
          {PHOTO_KIND_ORDER.filter((k) => grouped[k].length > 0).map((kind) => (
            <div key={kind} className="space-y-2">
              <p className="text-xs font-medium text-muted-foreground uppercase tracking-wide">
                {PHOTO_KIND_LABELS[kind]} ({grouped[kind].length})
              </p>
              <div className="grid grid-cols-3 gap-2">
                {grouped[kind].map((photo, idx) => {
                  const allPhotos = photos
                  const globalIdx = allPhotos.findIndex((p) => p.id === photo.id)
                  return (
                    <div
                      key={photo.id}
                      className="relative group aspect-square rounded-md bg-muted/50 border border-border/40 overflow-hidden cursor-pointer"
                      onClick={() => setLightboxIndex(globalIdx)}
                    >
                      {photo.signed_url ? (
                        // eslint-disable-next-line @next/next/no-img-element
                        <img
                          src={photo.signed_url}
                          alt={`${kind} photo ${idx + 1}`}
                          className="h-full w-full object-cover"
                        />
                      ) : (
                        <div className="h-full w-full flex items-center justify-center">
                          <span className="text-xs text-muted-foreground capitalize">{kind}</span>
                        </div>
                      )}
                      <button
                        className="absolute top-1 right-1 h-5 w-5 rounded-full bg-black/60 text-white flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity"
                        onClick={(e) => {
                          e.stopPropagation()
                          if (window.confirm('Remove this photo?')) {
                            deleteMutation.mutate(photo.id)
                          }
                        }}
                      >
                        <X className="h-3 w-3" />
                      </button>
                    </div>
                  )
                })}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Lightbox */}
      {lightboxIndex !== null && photos[lightboxIndex] && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/90"
          onClick={() => setLightboxIndex(null)}
        >
          <div
            className="relative max-w-3xl w-full mx-4"
            onClick={(e) => e.stopPropagation()}
          >
            {photos[lightboxIndex].signed_url ? (
              // eslint-disable-next-line @next/next/no-img-element
              <img
                src={photos[lightboxIndex].signed_url!}
                alt="Booking photo"
                className="w-full max-h-[80vh] object-contain rounded-xl"
              />
            ) : (
              <div className="h-64 rounded-xl bg-muted flex items-center justify-center">
                <span className="text-sm text-muted-foreground">No preview</span>
              </div>
            )}

            {/* Caption + kind */}
            <div className="mt-3 flex items-center justify-between px-1">
              <div>
                <span className="text-xs text-white/70 uppercase tracking-wide">
                  {PHOTO_KIND_LABELS[photos[lightboxIndex].kind]}
                </span>
                {photos[lightboxIndex].caption && (
                  <p className="text-sm text-white/90 mt-0.5">{photos[lightboxIndex].caption}</p>
                )}
              </div>
              <span className="text-xs text-white/50 tabular-nums">
                {lightboxIndex + 1} / {photos.length}
              </span>
            </div>

            {/* Nav */}
            {photos.length > 1 && (
              <>
                <Button
                  variant="ghost"
                  size="icon"
                  className="absolute left-2 top-1/2 -translate-y-1/2 bg-black/40 hover:bg-black/60 text-white h-9 w-9"
                  disabled={lightboxIndex === 0}
                  onClick={(e) => { e.stopPropagation(); setLightboxIndex((i) => Math.max(0, (i ?? 0) - 1)) }}
                >
                  <ChevronLeft className="h-5 w-5" />
                </Button>
                <Button
                  variant="ghost"
                  size="icon"
                  className="absolute right-2 top-1/2 -translate-y-1/2 bg-black/40 hover:bg-black/60 text-white h-9 w-9"
                  disabled={lightboxIndex === photos.length - 1}
                  onClick={(e) => { e.stopPropagation(); setLightboxIndex((i) => Math.min(photos.length - 1, (i ?? 0) + 1)) }}
                >
                  <ChevronRight className="h-5 w-5" />
                </Button>
              </>
            )}

            <Button
              variant="ghost"
              size="icon"
              className="absolute top-2 right-2 bg-black/40 hover:bg-black/60 text-white h-7 w-7"
              onClick={() => setLightboxIndex(null)}
            >
              <X className="h-4 w-4" />
            </Button>
          </div>
        </div>
      )}
    </div>
  )
}

import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

interface Params {
  params: Promise<{ id: string }>
}

export async function GET(_request: NextRequest, { params }: Params) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { id } = await params
  if (!z.string().uuid().safeParse(id).success) {
    return NextResponse.json({ error: 'Invalid booking ID' }, { status: 400 })
  }

  try {
    const supabase = await createClient()

    // Verify booking belongs to studio
    const { data: booking, error: bookingError } = await supabase
      .from('bookings')
      .select('id')
      .eq('id', id)
      .eq('studio_id', authUser.studioId)
      .single()

    if (bookingError || !booking) {
      return NextResponse.json({ error: 'Booking not found' }, { status: 404 })
    }

    const { data: photos, error } = await supabase
      .from('booking_photos')
      .select('id, kind, caption, taken_at, storage_path')
      .eq('booking_id', id)
      .eq('studio_id', authUser.studioId)
      .order('taken_at', { ascending: true })

    if (error) {
      logger.error({ err: error, bookingId: id }, 'photos list failed')
      return NextResponse.json({ error: 'Failed to fetch photos' }, { status: 500 })
    }

    // Generate signed URLs for each photo (1hr expiry)
    const photosWithUrls = await Promise.all(
      (photos ?? []).map(async (photo) => {
        const { data } = await supabase.storage
          .from('design-assets')
          .createSignedUrl(photo.storage_path, 3600)
        return { ...photo, signed_url: data?.signedUrl ?? null }
      })
    )

    return NextResponse.json({ data: photosWithUrls })
  } catch (err) {
    logger.error({ err, bookingId: id }, 'photos GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

interface Params {
  params: Promise<{ id: string; photoId: string }>
}

export async function DELETE(_request: NextRequest, { params }: Params) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { id, photoId } = await params
  if (
    !z.string().uuid().safeParse(id).success ||
    !z.string().uuid().safeParse(photoId).success
  ) {
    return NextResponse.json({ error: 'Invalid ID' }, { status: 400 })
  }

  try {
    const supabase = await createClient()

    // Fetch photo to get storage_path and verify ownership
    const { data: photo, error: fetchError } = await supabase
      .from('booking_photos')
      .select('id, storage_path')
      .eq('id', photoId)
      .eq('booking_id', id)
      .eq('studio_id', authUser.studioId)
      .single()

    if (fetchError || !photo) {
      return NextResponse.json({ error: 'Photo not found' }, { status: 404 })
    }

    // Delete from storage first
    const { error: storageError } = await supabase.storage
      .from('design-assets')
      .remove([photo.storage_path])

    if (storageError) {
      logger.error({ err: storageError, photoId }, 'photo storage delete failed')
      // Continue to delete the DB record even if storage delete fails
    }

    // Delete DB record
    const { error: deleteError } = await supabase
      .from('booking_photos')
      .delete()
      .eq('id', photoId)
      .eq('studio_id', authUser.studioId)

    if (deleteError) {
      logger.error({ err: deleteError, photoId }, 'photo DB delete failed')
      return NextResponse.json({ error: 'Failed to delete photo' }, { status: 500 })
    }

    return new NextResponse(null, { status: 204 })
  } catch (err) {
    logger.error({ err, photoId }, 'photo DELETE unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

