1	import { NextRequest, NextResponse } from 'next/server'
2	import { z } from 'zod'
3	import { getAuthenticatedUser } from '@/lib/supabase/server'
4	import { createClient } from '@/lib/supabase/server'
5	import { authedRatelimit } from '@/lib/rate-limit'
6	import { logger } from '@/lib/logger'
7	
8	const UpdateBookingSchema = z.object({
9	  artist_id: z.string().uuid().optional(),
10	  service_id: z.string().uuid().nullable().optional(),
11	  location_id: z.string().uuid().nullable().optional(),
12	  scheduled_at: z.string().datetime().optional(),
13	  duration_min: z.number().int().min(15).max(480).optional(),
14	  price_cents: z.number().int().min(0).optional(),
15	  deposit_cents: z.number().int().min(0).optional(),
16	  notes: z.string().max(2000).nullable().optional(),
17	  client_notes: z.string().max(2000).nullable().optional(),
18	})
19	
20	interface Params {
21	  params: Promise<{ id: string }>
22	}
23	
24	export async function GET(_request: NextRequest, { params }: Params) {
25	  const authUser = await getAuthenticatedUser()
26	  if (!authUser) {
27	    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
28	  }
29	
30	  const { success } = await authedRatelimit.limit(authUser.user.id)
31	  if (!success) {
32	    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
33	  }
34	
35	  const { id } = await params
36	  if (!z.string().uuid().safeParse(id).success) {
37	    return NextResponse.json({ error: 'Invalid booking ID' }, { status: 400 })
38	  }
39	
40	  try {
41	    const supabase = await createClient()
42	    const { data, error } = await supabase
43	      .from('bookings')
44	      .select(
45	        `
46	        *,
47	        client:clients(id, first_name, last_name, email, phone, total_sessions, total_spent_cents, tags, notes),
48	        artist:artists(id, display_name, avatar_url, sort_order),
49	        service:services(id, name, duration_min, base_price_cents, deposit_cents, color),
50	        location:locations(id, name, address, city),
51	        photos:booking_photos(id, kind, caption, taken_at, storage_path)
52	      `
53	      )
54	      .eq('id', id)
55	      .eq('studio_id', authUser.studioId)
56	      .single()
57	
58	    if (error || !data) {
59	      return NextResponse.json({ error: 'Booking not found' }, { status: 404 })
60	    }
61	
62	    return NextResponse.json({ data })
63	  } catch (err) {
64	    logger.error({ err, bookingId: id }, 'booking GET unexpected error')
65	    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
66	  }
67	}
68	
69	export async function PATCH(request: NextRequest, { params }: Params) {
70	  const authUser = await getAuthenticatedUser()
71	  if (!authUser) {
72	    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
73	  }
74	
75	  const { success } = await authedRatelimit.limit(authUser.user.id)
76	  if (!success) {
77	    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
78	  }
79	
80	  const { id } = await params
81	  if (!z.string().uuid().safeParse(id).success) {
82	    return NextResponse.json({ error: 'Invalid booking ID' }, { status: 400 })
83	  }
84	
85	  let body: unknown
86	  try {
87	    body = await request.json()
88	  } catch {
89	    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
90	  }
91	
92	  const parsed = UpdateBookingSchema.safeParse(body)
93	  if (!parsed.success) {
94	    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
95	  }
96	
97	  if (Object.keys(parsed.data).length === 0) {
98	    return NextResponse.json({ error: 'No fields to update' }, { status: 400 })
99	  }
100	
101	  try {
102	    const supabase = await createClient()
103	    const { data, error } = await supabase
104	      .from('bookings')
105	      .update(parsed.data)
106	      .eq('id', id)
107	      .eq('studio_id', authUser.studioId)
108	      .select('id, scheduled_at, end_at, duration_min, status, price_cents, notes, updated_at')
109	      .single()
110	
111	    if (error) {
112	      if (error.code === '23P01') {
113	        return NextResponse.json(
114	          { error: 'That time slot is already booked for this artist' },
115	          { status: 409 }
116	        )
117	      }
118	      if (error.code === 'PGRST116') {
119	        return NextResponse.json({ error: 'Booking not found' }, { status: 404 })
120	      }
121	      logger.error({ err: error, bookingId: id }, 'booking PATCH failed')
122	      return NextResponse.json({ error: 'Failed to update booking' }, { status: 500 })
123	    }
124	
125	    return NextResponse.json({ data })
126	  } catch (err) {
127	    logger.error({ err, bookingId: id }, 'booking PATCH unexpected error')
128	    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
129	  }
130	}
131	
132	export async function DELETE(_request: NextRequest, { params }: Params) {
133	  const authUser = await getAuthenticatedUser()
134	  if (!authUser) {
135	    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
136	  }
137	
138	  const { success } = await authedRatelimit.limit(authUser.user.id)
139	  if (!success) {
140	    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
141	  }
142	
143	  const { id } = await params
144	  if (!z.string().uuid().safeParse(id).success) {
145	    return NextResponse.json({ error: 'Invalid booking ID' }, { status: 400 })
146	  }
147	
148	  try {
149	    const supabase = await createClient()
150	    const { error } = await supabase
151	      .from('bookings')
152	      .update({ status: 'cancelled', cancelled_at: new Date().toISOString() })
153	      .eq('id', id)
154	      .eq('studio_id', authUser.studioId)
155	
156	    if (error) {
157	      if (error.code === 'PGRST116') {
158	        return NextResponse.json({ error: 'Booking not found' }, { status: 404 })
159	      }
160	      logger.error({ err: error, bookingId: id }, 'booking DELETE failed')
161	      return NextResponse.json({ error: 'Failed to cancel booking' }, { status: 500 })
162	    }
163	
164	    return new NextResponse(null, { status: 204 })
165	  } catch (err) {
166	    logger.error({ err, bookingId: id }, 'booking DELETE unexpected error')
167	    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
168	  }
169	}
